import * as THREE from 'three';
const palette={3:0x8acaff,4:0xbe96ff,5:0xffd78a};
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function glowTexture(){const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d'),gradient=ctx.createRadialGradient(32,32,0,32,32,32);gradient.addColorStop(0,'rgba(255,255,255,1)');gradient.addColorStop(.15,'rgba(255,255,255,.8)');gradient.addColorStop(.5,'rgba(255,255,255,.14)');gradient.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);return new THREE.CanvasTexture(canvas);}
function stage(container){let renderer;try{renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});}catch{return null;}renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));container.append(renderer.domElement);const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(55,1,.1,200);camera.position.z=18;const clock=new THREE.Clock();let frame,dead=false;const resize=()=>{const {width,height}=container.getBoundingClientRect();if(!width||!height)return;renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix();};const observer=new ResizeObserver(resize);observer.observe(container);resize();const dispose=()=>{if(dead)return;dead=true;cancelAnimationFrame(frame);observer.disconnect();const geometries=new Set(),materials=new Set(),textures=new Set();scene.traverse(obj=>{if(obj.geometry)geometries.add(obj.geometry);for(const m of Array.isArray(obj.material)?obj.material:[obj.material])if(m){materials.add(m);if(m.map)textures.add(m.map);}});geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());textures.forEach(t=>t.dispose());renderer.dispose();renderer.domElement.remove();};return {scene,camera,renderer,dispose,animate(update){const tick=()=>{if(dead)return;frame=requestAnimationFrame(tick);const delta=Math.min(clock.getDelta(),.05),elapsed=clock.elapsedTime;update(elapsed,delta);renderer.render(scene,camera);};tick();}};}
function particles(scene,color,count=400){const positions=new Float32Array(count*3);for(let i=0;i<count;i++){positions[i*3]=(Math.random()-.5)*65;positions[i*3+1]=(Math.random()-.5)*42;positions[i*3+2]=-Math.random()*100;}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));const material=new THREE.PointsMaterial({color,size:.26,map:glowTexture(),transparent:true,depthWrite:false,blending:THREE.AdditiveBlending});const points=new THREE.Points(geometry,material);scene.add(points);return points;}
export function mountWish(container,rarity,onFinish){const s=stage(container);let timer;const duration=reduced()?500:4400;timer=setTimeout(onFinish,duration);if(!s)return ()=>clearTimeout(timer);const {scene,camera}=s,color=palette[rarity];scene.fog=new THREE.FogExp2(0x101d42,.012);const dust=particles(scene,color,reduced()?90:600),portal=new THREE.Group();scene.add(portal);portal.position.z=-18;
 for(let i=0;i<5;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(4+i*.45,.018,6,110),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.5-i*.07}));ring.rotation.x=i*.13;ring.rotation.y=i*.16;portal.add(ring);}
 const star=new THREE.Mesh(new THREE.OctahedronGeometry(.45),new THREE.MeshBasicMaterial({color:0xffffff}));scene.add(star);const halo=new THREE.Sprite(new THREE.SpriteMaterial({map:glowTexture(),color,blending:THREE.AdditiveBlending,depthWrite:false}));halo.scale.set(5,5,1);star.add(halo);
 const trails=new THREE.Group();scene.add(trails);for(let i=0;i<32;i++){const geometry=new THREE.CylinderGeometry(.015,.08,1+Math.random()*5,4),material=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.35+Math.random()*.4});const trail=new THREE.Mesh(geometry,material);trail.rotation.x=Math.PI/2;trail.position.set((Math.random()-.5)*25,(Math.random()-.5)*15,-Math.random()*65);trails.add(trail);}
 s.animate((t,dt)=>{const motion=reduced()?0:1;portal.rotation.z=t*.35*motion;portal.rotation.y=Math.sin(t*.4)*.15*motion;star.position.set(Math.sin(t*.7)*2*motion,Math.cos(t*.8)*1.3*motion,-12+t*3*motion);star.rotation.y=t*motion;star.rotation.z=t*.5*motion;halo.material.opacity=.65+Math.sin(t*3)*.2;camera.position.z=18-Math.min(t,3.5)*3.5*motion;camera.rotation.z=Math.sin(t*.5)*.035*motion;dust.rotation.z=t*.025*motion;for(const trail of trails.children){trail.position.z+=dt*(14+t*8)*motion;if(trail.position.z>camera.position.z)trail.position.z=-65;}const p=dust.geometry.attributes.position;for(let i=0;i<p.count;i++){p.array[i*3+2]+=dt*8*motion;if(p.array[i*3+2]>20)p.array[i*3+2]=-100;}p.needsUpdate=true;});return ()=>{clearTimeout(timer);s.dispose();};}
export function mountRewardScene(container,reward){const s=stage(container);if(!s)return ()=>{};const {scene,camera}=s,color=palette[reward.stars];camera.position.z=16;const dust=particles(scene,color,reduced()?60:200);const rings=new THREE.Group();scene.add(rings);rings.position.z=-8;for(let i=0;i<3;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(5+i*.8,.016,6,120),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.25}));ring.rotation.x=i*.3;ring.rotation.y=i*.3;rings.add(ring);}let gem;
 if(reward.type!=='character'){scene.add(new THREE.AmbientLight(0xffffff,2));const key=new THREE.PointLight(color,120);key.position.set(3,4,5);scene.add(key);gem=new THREE.Group();scene.add(gem);const material=new THREE.MeshStandardMaterial({color,metalness:.4,roughness:.18});let geometry;if(reward.id==='stick')geometry=new THREE.CylinderGeometry(.14,.22,4,8);else if(reward.id==='stone')geometry=new THREE.DodecahedronGeometry(1.3,0);else if(reward.id==='leaf')geometry=new THREE.OctahedronGeometry(1.5,0);else geometry=new THREE.OctahedronGeometry(1.6,0);const mesh=new THREE.Mesh(geometry,material);if(reward.id==='leaf')mesh.scale.set(.7,1.4,.12);gem.add(mesh);const outline=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({color:0xffffff,wireframe:true,transparent:true,opacity:.15}));outline.scale.setScalar(1.005);mesh.add(outline);}
 let px=0,py=0;const pointer=e=>{const b=container.getBoundingClientRect();px=(e.clientX-b.left)/b.width-.5;py=(e.clientY-b.top)/b.height-.5;};window.addEventListener('pointermove',pointer,{passive:true});s.animate((t)=>{const motion=reduced()?0:1;rings.rotation.z=t*.06*motion;dust.rotation.z=-t*.02*motion;if(gem){gem.rotation.y=t*.5*motion+px*.7;gem.rotation.z=Math.sin(t*.6)*.18*motion;gem.rotation.x=py*.25;gem.position.y=Math.sin(t*1.5)*.2*motion;}camera.position.x+=(px*.6*motion-camera.position.x)*.04;});return ()=>{window.removeEventListener('pointermove',pointer);s.dispose();};}
